// Manager Multiclub V1.0.14 · Tallaje técnicos PDF/contador robusto
(() => {
  "use strict";

  const CRESTS = Object.freeze({
    "cr-bahia-algeciras": "data:image/jpeg;base64,",
    "cd-rinconcillo": "data:image/jpeg;base64,"
  });

  function clubSlug() {
    try { return String(currentMulticlubClub?.slug || ""); } catch (_) { return ""; }
  }
  function clubName() {
    try {
      if (typeof currentClubFullName === "function") return currentClubFullName();
      return currentMulticlubClub?.nombre || currentMulticlubClub?.nombre_corto || "Manager Multiclub";
    } catch (_) { return "Manager Multiclub"; }
  }
  function clubUpper() {
    return clubName().toLocaleUpperCase("es-ES");
  }

  function currentRows() {
    try { return typeof staffSizingRows === "function" ? staffSizingRows() : []; }
    catch (_) { return []; }
  }

  function fixStaffSizingStats() {
    const stats = document.getElementById("staffSizingStats");
    if (!stats) return;
    const rows = currentRows();
    const sized = rows.filter(row => ["si","sí"].includes(String(row["Tallaje realizado"] || "").toLowerCase())).length;
    const desired = `<span><b>${rows.length}</b> ${rows.length === 1 ? "miembro" : "miembros"}</span><span><b>${sized}</b> ${sized === 1 ? "tallaje realizado" : "tallajes realizados"}</span>`;
    if (stats.innerHTML !== desired) stats.innerHTML = desired;
  }

  function openStaffSizingPdfV1014() {
    const rows = currentRows();
    if (!rows.length) {
      if (typeof toast === "function") toast("No hay tallajes del cuerpo técnico para generar el PDF");
      return;
    }
    if (!window.jspdf?.jsPDF) {
      if (typeof toast === "function") toast("No se pudo cargar el generador PDF");
      return;
    }
    const { jsPDF } = window.jspdf;
    if (typeof jsPDF.API.autoTable !== "function" && !window.jspdfAutoTable) {
      if (typeof toast === "function") toast("No se pudo cargar la tabla del PDF");
      return;
    }

    const viewer = window.open("about:blank", "_blank");
    if (viewer) {
      try {
        viewer.document.title = `Tallaje cuerpo técnico · ${clubName()}`;
        viewer.document.body.innerHTML = '<div style="font:16px Arial,sans-serif;padding:32px;color:#123">Generando PDF del tallaje técnico…</div>';
      } catch (_) {}
    }

    try {
      const labels = Object.keys(rows[0]);
      const team = document.getElementById("staffSizingTeam")?.value || "Todos los equipos";
      const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();

      doc.setProperties({
        title: `Tallaje cuerpo técnico · ${team}`,
        subject: `Tallaje del cuerpo técnico · ${clubName()}`,
        author: `${clubName()} Manager`,
        creator: `${clubName()} Manager`
      });

      doc.setFillColor(8, 42, 78);
      doc.rect(0, 0, pageWidth, 30, "F");

      const crest = CRESTS[clubSlug()];
      if (crest) {
        // JPEG precompuesto sobre el mismo azul de cabecera: no depende de
        // canvas, CORS, file:// ni del estado de carga del DOM.
        doc.addImage(crest, "JPEG", 7.5, 2.5, 25, 25);
      }

      doc.setTextColor(255,255,255);
      doc.setFont(undefined, "bold");
      doc.setFontSize(15);
      doc.text(clubUpper(), 36, 11);
      doc.setFont(undefined, "normal");
      doc.setFontSize(11);
      doc.text("Tallaje exclusivo del cuerpo técnico", 36, 19);
      doc.setFontSize(8);
      doc.text(`Equipo: ${team} · ${rows.length} ${rows.length === 1 ? "miembro" : "miembros"} · ${new Date().toLocaleDateString("es-ES")}`, 36, 25);

      doc.autoTable({
        head: [labels],
        body: rows.map(row => labels.map(label => String(row[label] ?? "-"))),
        startY: 35,
        theme: "grid",
        styles: { fontSize: 6.2, cellPadding: 1.25, overflow: "linebreak", valign: "middle" },
        headStyles: { fillColor: [17,93,151], textColor: 255, fontStyle: "bold", fontSize: 6.1 },
        alternateRowStyles: { fillColor: [244,248,251] },
        margin: { left: 7, right: 7, bottom: 12 },
        didDrawPage: () => {
          const current = doc.internal.getCurrentPageInfo().pageNumber;
          doc.setTextColor(90);
          doc.setFontSize(7);
          doc.text(`${clubName()} · Tallaje del cuerpo técnico`, 7, pageHeight - 5);
          doc.text(`Página ${current}`, pageWidth - 22, pageHeight - 5);
        }
      });

      const blob = doc.output("blob");
      const pdfUrl = URL.createObjectURL(blob);
      if (viewer && !viewer.closed) viewer.location.replace(pdfUrl);
      else {
        const link = document.createElement("a");
        link.href = pdfUrl;
        link.target = "_blank";
        link.rel = "noopener";
        document.body.appendChild(link);
        link.click();
        link.remove();
      }
      setTimeout(() => URL.revokeObjectURL(pdfUrl), 60000);
    } catch (error) {
      console.error("PDF tallaje técnico V1.0.14", error);
      try { if (viewer && !viewer.closed) viewer.close(); } catch (_) {}
      if (typeof toast === "function") toast("No se pudo generar el PDF del tallaje técnico");
    }
  }

  function installPdfButton() {
    const oldButton = document.getElementById("printStaffSizingReport");
    if (!oldButton || oldButton.dataset.multiclubV1014 === "1") return;
    // Clonar elimina el listener antiguo que quedó ligado a la función previa.
    const button = oldButton.cloneNode(true);
    button.dataset.multiclubV1014 = "1";
    oldButton.replaceWith(button);
    button.addEventListener("click", openStaffSizingPdfV1014);
  }

  function installStatsWatcher() {
    const stats = document.getElementById("staffSizingStats");
    if (!stats || stats.dataset.multiclubV1014 === "1") return;
    stats.dataset.multiclubV1014 = "1";
    let applying = false;
    const observer = new MutationObserver(() => {
      if (applying) return;
      applying = true;
      try { fixStaffSizingStats(); } finally { applying = false; }
    });
    observer.observe(stats, { childList: true, subtree: true, characterData: true });
    fixStaffSizingStats();

    document.getElementById("staffSizingTeam")?.addEventListener("change", () => setTimeout(fixStaffSizingStats, 0));
  }

  function install() {
    installPdfButton();
    installStatsWatcher();
    setTimeout(fixStaffSizingStats, 0);
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", install, { once: true });
  else install();
  window.addEventListener("load", () => {
    install();
    setTimeout(install, 250);
    setTimeout(install, 1000);
  }, { once: true });
})();
